page='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>Astra 三任务两层比较</title><style>body{max-width:1100px;margin:32px auto;padding:0 20px;font:16px/1.7 system-ui,Microsoft YaHei;color:#1b3040}select{padding:9px;margin:8px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd4dc;padding:8px}th{background:#eef2f5}small{color:#506071}</style><a href="index.html">返回研究目录</a><h1>同任务的技术提及与要求方式</h1><p>第一层是可辨识本人职责或资格提及，含明确示例、任选与分支未解；对象未解不计正例。后四列在提及广告内去重，可重叠，不得相加。职责指严格本人使用或开发；协作联系另见CSV。</p><select id="task"><option value="ROBOT_MODEL">机器人模型</option><option value="ROBOT_RUNTIME">机器人运行软件</option><option value="BOARD_CIRCUIT">板级电路</option></select><select id="code"></select><div id="summary"></div><table><thead><tr><th>公司</th><th>任务广告</th><th>提及 P/N</th><th>未知对象</th><th>来源排除</th><th>职责</th><th>必备</th><th>一般</th><th>优先</th><th>含未解分支</th></tr></thead><tbody id="body"></tbody></table><p><small>N小于10为公司小样本；未记正例不等于企业没有该能力。语境无条件格与公司未知界限请查17职能查询页。</small></p><p><a href="tables/V3_two_layer_company_points.csv">完整公司点值与四情景</a> · <a href="tables/V3_two_layer_evidence.csv">原文证据</a></p><script>const data=__DATA__,names=__NAMES__;const t=document.getElementById('task'),c=document.getElementById('code');const esc=x=>String(x).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));function labels(){const m=new Map(data.filter(x=>x[0]===t.value).map(x=>[x[1],x[2]]));c.innerHTML=[...m].map(x=>'<option value="'+esc(x[0])+'">'+esc(x[1])+'</option>').join('');c.value=t.value==='ROBOT_MODEL'?'SK_PYTHON':t.value==='ROBOT_RUNTIME'?'SK_CPP':'SK_ALTIUM';render()}function render(){const rr=data.filter(x=>x[0]===t.value&&x[1]===c.value);document.getElementById('summary').textContent='当前任务 '+rr.reduce((s,x)=>s+Number(x[4]),0)+' 条广告；各公司点值如下。';document.getElementById('body').innerHTML=rr.map(x=>'<tr><td>'+esc(names[x[3]]||x[3])+(Number(x[6])<10?'（小样本）':'')+'</td><td>'+x[4]+'</td><td>'+x[5]+'/'+x[6]+'</td>'+x.slice(7).map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')}t.onchange=labels;c.onchange=render;labels();</script></html>'''
